messages.content:
Generate a standalone C reproducer that triggers this vulnerability:

File: libtiff/tif_luv.c
Line: 366
Function: LogLuvDecode32
Bug type: out-of-bounds-read
CWE: CWE-125
Explanation: Same logic error as in LogL16Decode: the non-run branch reads the count byte with 'rc = *bp++;' without decrementing 'cc' for it. 'cc' is only decremented for data bytes in 'while (--cc && rc-- && i < npixels)'. This leaves 'cc' one too large after consuming the data bytes, so the next iteration tests 'cc > 0' and dereferences '*bp' (e.g., at line 354) past the end of the input buffer, resulting in an out-of-bounds read.

Source context:
```c
      326: 
      327:     (void)s;
      328:     assert(s == 0);
      329:     sp = DecoderState(tif);
      330:     assert(sp != NULL);
      331: 
      332:     npixels = occ / sp->pixel_size;
      333: 
      334:     if (sp->user_datafmt == SGILOGDATAFMT_RAW)
      335:         tp = (uint32_t *)op;
      336:     else
      337:     {
      338:         if (sp->tbuflen < npixels)
      339:         {
      340:             TIFFErrorExtR(tif, module, "Translation buffer too short");
      341:             return (0);
      342:         }
      343:         tp = (uint32_t *)sp->tbuf;
      344:     }
      345:     _TIFFmemset((void *)tp, 0, npixels * sizeof(tp[0]));
      346: 
      347:     bp = (unsigned char *)tif->tif_rawcp;
      348:     cc = tif->tif_rawcc;
      349:     /* get each byte string */
      350:     for (shft = 24; shft >= 0; shft -= 8)
      351:     {
      352:         for (i = 0; i < npixels && cc > 0;)
      353:         {
      354:             if (*bp >= 128)
      355:             { /* run */
      356:                 if (cc < 2)
      357:                     break;
      358:                 rc = *bp++ + (2 - 128);
      359:                 b = (uint32_t)*bp++ << shft;
      360:                 cc -= 2;
      361:                 while (rc-- && i < npixels)
      362:                     tp[i++] |= b;
      363:             }
      364:             else
      365:             {               /* non-run */
>>>   366:                 rc = *bp++; /* nul is noop */
      367:                 while (--cc && rc-- && i < npixels)
      368:                     tp[i++] |= (uint32_t)*bp++ << shft;
      369:             }
      370:         }
      371:         if (i != npixels)
      372:         {
      373:             TIFFErrorExtR(tif, module,
      374:                           "Not enough data at row %" PRIu32
      375:                           " (short %" TIFF_SSIZE_FORMAT " pixels)",
      376:                           tif->tif_row, npixels - i);
      377:             tif->tif_rawcp = (uint8_t *)bp;
      378:             tif->tif_rawcc = cc;
      379:             return (0);
      380:         }
      381:     }
      382:     (*sp->tfunc)(sp, op, npixels);
      383:     tif->tif_rawcp = (uint8_t *)bp;
      384:     tif->tif_rawcc = cc;
      385:     return (1);
      386: }
      387: 
      388: /*
      389:  * Decode a strip of pixels.  We break it into rows to
      390:  * maintain synchrony with the encode algorithm, which
      391:  * is row by row.
      392:  */
      393: static int LogLuvDecodeStrip(TIFF *tif, uint8_t *bp, tmsize_t cc, uint16_t s)
      394: {
      395:     tmsize_t rowlen = TIFFScanlineSize(tif);
      396: 
      397:     if (rowlen == 0)
      398:         return 0;
      399: 
      400:     assert(cc % rowlen == 0);
      401:     while (cc && (*tif->tif_decoderow)(tif, bp, rowlen, s))
      402:     {
      403:         bp += rowlen;
      404:         cc -= rowlen;
      405:     }
      406:     return (cc == 0);
```

The reproducer will be compiled with:
  clang -fsanitize=address -g -O0 -I/tmp/libtiff_upstream reproducer.c -L/tmp/libtiff_upstream/build/.libs -ltiff -lm

The project source root is: /tmp/libtiff_upstream
